#include <cstddef>
#include <stdexcept>
#include <type_traits>
#include <vector>

template <class T>
class Span {
  T* p_ = nullptr;
  std::size_t n_ = 0;
public:
  constexpr Span() noexcept = default;
  constexpr Span(T* p, std::size_t n) noexcept : p_(p), n_(n) {}
  template <std::size_t N>
  constexpr Span(T (&arr)[N]) noexcept : p_(arr), n_(N) {}
  template <class U, class A,
            class = std::enable_if_t<std::is_convertible_v<U(*)[], T(*)[]>>>
  Span(std::vector<U, A>& v) noexcept : p_(v.data()), n_(v.size()) {}
  template <class U, class A,
            class = std::enable_if_t<std::is_const_v<T> &&
                                     std::is_convertible_v<const U(*)[], T(*)[]>>>
  Span(const std::vector<U, A>& v) noexcept : p_(v.data()), n_(v.size()) {}

  constexpr T& operator[](std::size_t i) const noexcept { return p_[i]; }
  constexpr std::size_t size() const noexcept { return n_; }
  constexpr bool empty() const noexcept { return n_ == 0; }
  constexpr T* data() const noexcept { return p_; }
  constexpr T* begin() const noexcept { return p_; }
  constexpr T* end() const noexcept { return p_ + n_; }

  Span subspan(std::size_t off, std::size_t cnt) const {
    if (off > n_ || cnt > n_ - off)   // no overflow: compare against n_ - off
      throw std::out_of_range("subspan");
    return Span(p_ + off, cnt);
  }
};

